+    final log = await readLog();
+    final alphaContexts = log
+        .split('\n')
+        .where(
+          (line) =>
+              line.contains('boot_stage context') && line.contains(alphaId),
+        )
+        .toList();
+    expect(alphaContexts, isNotEmpty);
+    expect(
