+    expect(
+      cache.match('/s/b.jsonl', sizeBytes: 1, mtimeMs: 1),
+      isNull,
+      reason: 'the least-recently-used entry was evicted',
+    );
+    expect(cache.match('/s/c.jsonl', sizeBytes: 1, mtimeMs: 1), isNotNull);
+  });
+
+  test('clear() empties the cache', () {
