+      ..remember(
+        '/s/a.jsonl',
+        sizeBytes: 10,
+        mtimeMs: 1,
+        context: contextOf('a'),
+      )
+      ..clear();
+    expect(cache.length, 0);
+    expect(cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1), isNull);
+  });
