+    required int mtimeMs,
+    required SessionContext context,
+    int variant = 0,
+  }) {
+    _entries.remove(path);
+    _entries[path] = _Entry(
+      sizeBytes: sizeBytes,
+      mtimeMs: mtimeMs,
+      variant: variant,
+      context: context,
+    );
+    while (_entries.length > capacity) {
+      _entries.remove(_entries.keys.first);
+    }
+  }
