    'content': content.map((block) => block.toJson()).toList(),
    'isError': isError,
    'timestamp': timestamp.millisecondsSinceEpoch,
  };

  /// Deserializes from a JSON map produced by [toJson].
  factory ToolResultMessage.fromJson(Map<String, dynamic> json) =>
