    final previous = _captureRestoreWiring();
    final entry = _pinnedRestoreEntry(customProviderName);
    final built = _buildRestoredModel(
      providerKind: providerKind,
      modelId: modelId,
      baseUrl: baseUrl,
      entry: entry,
